class Solution { public: int minNumberOfFrogs(string croak){string order="croak";int stage[5]={},active=0,answer=0;for(char value:croak){int index=order.find(value);if(index<0)return -1;if(index==0){++stage[0];answer=max(answer,++active);}else{if(!stage[index-1])return -1;--stage[index-1];if(index==4)--active;else ++stage[index];}}for(int i=0;i<4;++i)if(stage[i])return -1;return active? -1:answer;} };
